import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  Tooltip,
  PieChart,
  Pie,
  Cell,
  Legend,
  LineChart,
  Line,
  ResponsiveContainer,
} from "recharts";
import Header from "../../components/Header/Header";
import Footer from "../../components/Footer/Footer";
import "./view-result-page.css";

const subjects = ["Computer Networks", "Data Structures", "OS", "OOPs", "DBMS"];

// Dummy evaluation data
const evaluations = [
  { cosine_similarity_score: 0.49, difficulty: "Medium", total_score: 1.6, subject: "Computer Networks" },
  { cosine_similarity_score: 0.29, difficulty: "Medium", total_score: 1.1, subject: "Computer Networks" },
  { cosine_similarity_score: 0.43, difficulty: "Medium", total_score: 1.3, subject: "Computer Networks" },
  { cosine_similarity_score: 0.32, difficulty: "Easy", total_score: 1.5, subject: "Data Structures" },
  { cosine_similarity_score: 0.34, difficulty: "Easy", total_score: 1.4, subject: "Data Structures" },
  { cosine_similarity_score: 0.48, difficulty: "Hard", total_score: 1.7, subject: "OS" },
  { cosine_similarity_score: 0.55, difficulty: "Hard", total_score: 1.9, subject: "OOPs" },
  { cosine_similarity_score: 0.60, difficulty: "Medium", total_score: 2.0, subject: "DBMS" },
];

// Aggregate total scores per subject for BarChart
const subjectScores = subjects.map((subject) => ({
  subject,
  total_score: evaluations
    .filter((e) => e.subject === subject)
    .reduce((sum, e) => sum + e.total_score, 0),
}));

// Count difficulty occurrences for PieChart
const difficultyCounts = evaluations.reduce<{ [key: string]: number }>((acc, curr) => {
  acc[curr.difficulty] = (acc[curr.difficulty] || 0) + 1;
  return acc;
}, {});

const pieChartData = Object.entries(difficultyCounts).map(([difficulty, count]) => ({
  name: difficulty,
  value: count,
}));

const COLORS = ["#0088FE", "#00C49F", "#FFBB28"];

// Generate dummy performance data for LineChart
const generatePerformanceData = () => {
  return subjects.map((subject) => ({
    subject,
    scores: Array.from({ length: 5 }, (_, i) => ({
      test: `Test ${i + 1}`,
      score: Math.random() * 2, // Random score between 0 and 2
    })),
  }));
};

const performanceData = generatePerformanceData();

const ViewResultPage: React.FC = () => {
  const [testId, setTestId] = useState<string>("");
  const [results, setResults] = useState<any[]>([]);
  const [message, setMessage] = useState<string | null>(null);
  const navigate = useNavigate();

  const fetchResults = async (e: React.FormEvent) => {
    e.preventDefault();
    setMessage(null);
    setResults([]);

    if (!testId.trim()) {
      setMessage("Please enter a valid Test ID.");
      return;
    }

    try {
      const response = await fetch("http://localhost:5000/viewresult", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ testid: testId }),
      });

      if (response.ok) {
        const data = await response.json();
        setResults(data.result);
        setMessage(null);
      } else {
        const error = await response.json();
        setMessage(`Error: ${error.error || "Failed to fetch results."}`);
      }
    } catch (err) {
      setMessage(`Error: ${err}`);
    }
  };

  const goToHomePage = () => {
    navigate("/");
  };

  return (
    <div className="App">
      <Header />
      <div className="result-container">
        {/* Left Side: Performance Analysis */}
        <div className="performance-section">
          <h2>Performance Analysis</h2>

          {/* Bar Chart */}
          <div className="chart-container">
            <h3>Subject Total Scores</h3>
            <BarChart width={500} height={300} data={subjectScores}>
              <XAxis dataKey="subject" />
              <YAxis />
              <Tooltip />
              <Bar dataKey="total_score" fill="#8884d8" />
            </BarChart>
          </div>

          {/* Pie Chart */}
          <div className="chart-container">
            <h3>Difficulty Distribution</h3>
            <PieChart width={400} height={400}>
              <Pie data={pieChartData} cx="50%" cy="50%" outerRadius={100} fill="#8884d8" dataKey="value">
                {pieChartData.map((_, index) => (
                  <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                ))}
              </Pie>
              <Tooltip />
              <Legend />
            </PieChart>
          </div>

          {/* Line Charts for Each Subject */}
          {performanceData.map((subjectData, index) => (
            <div key={index} className="chart-container">
              <h3>{subjectData.subject}</h3>
              <ResponsiveContainer width="95%" height={150}>
                <LineChart data={subjectData.scores}>
                  <XAxis dataKey="test" />
                  <YAxis domain={[0, 2]} />
                  <Tooltip />
                  <Line type="monotone" dataKey="score" stroke="#8884d8" />
                </LineChart>
              </ResponsiveContainer>
            </div>
          ))}
        </div>

        {/* Right Side: Test Results */}
        <div className="result-section">
          <h2>View Results</h2>
          <form onSubmit={fetchResults} className="result-form">
            <div className="form-group">
              <label htmlFor="testId">Test ID</label>
              <input
                type="text"
                id="testId"
                value={testId}
                onChange={(e) => setTestId(e.target.value)}
                placeholder="Enter Test ID"
                required
              />
            </div>
            <button type="submit" className="fetch-button">Fetch Results</button>
          </form>
          {message && <p className="feedback-message">{message}</p>}

          {results.length > 0 && (
            <div className="results-container">
              <h3>Results</h3>
              <table className="results-table">
                <thead>
                  <tr>
                    <th>Question</th>
                    <th>Your Answer</th>
                    <th>Reference Answer</th>
                  </tr>
                </thead>
                <tbody>
                  {results.map((result, index) => (
                    <tr key={index}>
                      <td>{result.question || "N/A"}</td>
                      <td>{result.answer || "N/A"}</td>
                      <td>{result.reference_answer || "N/A"}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}

          <button className="home-button" onClick={goToHomePage}>Go to Home Page</button>
        </div>
      </div>
      <Footer />
    </div>
  );
};

export default ViewResultPage;
